window.__votdWeek && window.__votdWeek({"week":"2028-05-29","reading":"Mosiah 29–Alma 4","days":[{"d":"2028-05-29","ref":"Mosiah 29:12","b":"Mosiah","c":29,"v":12,"he":"טוֹב כִּי־יִשָּׁפֵט הָאָדָם בִּידֵי אֱלֹהִים מִידֵי אָדָם כִּי מִשְׁפְּטֵי אֱלֹהִים צֶדֶק הֵם תָּמִיד וּמִשְׁפְּטֵי הָאָדָם לֹא־צֶדֶק הֵם תָּמִיד׃","en":"Now it is better that a man should be judged of God than of man, for the judgments of God are always just, but the judgments of man are not always just."},{"d":"2028-05-30","ref":"Mosiah 29:25","b":"Mosiah","c":29,"v":25,"he":"לָכֵן בַּחֲרוּ לָכֶם בְּקוֹל הָעָם שֹׁפְטִים לְמַעַן תִּשָּׁפְטוּ כְּפִי הַחֻקִּים אֲשֶׁר נִתְּנוּ לָכֶם מֵאֵת אֲבוֹתֵינוּ אֲשֶׁר צֶדֶק הֵם וַאֲשֶׁר נִתְּנוּ לָהֶם מִיַּד יְהוָה׃","en":"Therefore, choose you by the voice of this people, judges, that ye may be judged according to the laws which have been given you by our fathers, which are correct, and which were given them by the hand of the Lord."},{"d":"2028-05-31","ref":"Alma 1:24","b":"Alma","c":1,"v":24,"he":"כִּי קָשׁוּ לְבַב רַבִּים וַיִּמָּחוּ שְׁמוֹתָם וְלֹא נִזְכְּרוּ עוֹד בְּקֶרֶב עַם הָאֱלֹהִים וְגַם רַבִּים נִפְרְדוּ מִתּוֹכָם׃","en":"For the hearts of many were hardened, and their names were blotted out, that they were remembered no more among the people of God. And also many withdrew themselves from among them."},{"d":"2028-06-01","ref":"Alma 1:27","b":"Alma","c":1,"v":27,"he":"וַיִּתְּנוּ מֵרְכוּשָׁם אִישׁ כַּאֲשֶׁר הָיָה־לוֹ לָעֲנִיִּים וְלָאֶבְיוֹנִים וְלַחוֹלִים וְלַמְעֻנִּים וְלֹא לָבְשׁוּ בְּגָדִים יְקָרִים אַךְ הָיוּ נְקִיִּים וְנָאִים׃","en":"And they did impart of their substance, every man according to that which he had, to the poor, and the needy, and the sick, and the afflicted; and they did not wear costly apparel, yet they were neat and comely."},{"d":"2028-06-02","ref":"Alma 3:8","b":"Alma","c":3,"v":8,"he":"וְזֹאת נֶעֶשְׂתָה לְמַעַן יִבָּדֵל זַרְעָם מִזֶּרַע אֲחֵיהֶם לְמַעַן יִשְׁמֹר יְהוָה אֱלֹהִים אֶת־עַמּוֹ לְבִלְתִּי יִתְעָרְבוּ וְיַאֲמִינוּ בְּתוֹרוֹת לֹא־נְכוֹנוֹת אֲשֶׁר תִּהְיֶינָה לָהֶם לְמַשְׁחִית׃","en":"And this was done that their seed might be distinguished from the seed of their brethren, that thereby the Lord God might preserve his people, that they might not mix and believe in incorrect traditions which would prove their destruction."},{"d":"2028-06-03","ref":"Alma 3:27","b":"Alma","c":3,"v":27,"he":"כִּי כׇל־אִישׁ יְקַבֵּל שְׂכַר מִמֶּנּוּ אֲשֶׁר בָּחַר לִשְׁמֹעַ לוֹ וְזֹאת כְּדִבְרֵי רוּחַ הַנְּבוּאָה לָכֵן יְהִי כֶּאֱמֶת וַתִּתֹּם הַשָּׁנָה הַחֲמִישִׁית לִמְשֹׁל הַשֹּׁפְטִים׃","en":"For every man receiveth wages of him whom he listeth to obey, and this according to the words of the spirit of prophecy; therefore let it be according to the truth. And thus endeth the fifth year of the reign of the judges."},{"d":"2028-06-04","ref":"Alma 4:17","b":"Alma","c":4,"v":17,"he":"וְשֵׁם הָאִישׁ נֶפִיהָה וַיִּמָּנֶה לְשֹׁפֵט הָרֹאשׁ וַיֵּשֶׁב עַל־כִּסֵּא הַמִּשְׁפָּט לִשְׁפֹּט וְלִמְשֹׁל בָּעָם׃","en":"Now this man’s name was Nephihah, and he was appointed chief judge; and he sat in the judgment-seat to judge and to govern the people."}]});
